import { z } from "zod";

export const TIME_ZONE = "America/Los_Angeles";

export const SCORE_VERSION = "dinner-choice-scarcity-v2";

const nonempty = z.string().trim().min(1);

const timestamp = z.iso
  .datetime({ offset: true })
  .transform((value) => new Date(value).toISOString());

const date = z.iso.date();

const httpUrl = z.url({ protocol: /^https?$/ });

// Stop invalid URLs before the pathname refinement calls the URL constructor.
const resyUrl = z
  .url({ protocol: /^https$/, hostname: /^resy\.com$/, abort: true })
  .refine((value) => {
    const url = new URL(value);

    return /^\/cities\/[^/]+\/venues\/[^/]+$/.test(url.pathname) && !url.search && !url.hash;
  }, "Use a canonical Resy venue URL without query parameters or a trailing slash");

const localDateFormatter = new Intl.DateTimeFormat("en-CA", {
  timeZone: TIME_ZONE,
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
});

export function localDate(instant: string): string {
  return localDateFormatter.format(new Date(instant));
}

// Calendar arithmetic uses UTC only to avoid adding 24 hours across local DST changes.
export function addDays(day: string, count: number): string {
  const value = new Date(`${day}T00:00:00Z`);
  value.setUTCDate(value.getUTCDate() + count);

  return value.toISOString().slice(0, 10);
}

export const evidenceSchema = z.strictObject({
  url: httpUrl,
  observedAt: timestamp,
  quote: nonempty,
});

const slotSchema = z.strictObject({
  time: z.string().regex(/^(?:(?:18|19|20):[0-5]\d|21:00)$/),
  type: nonempty,
  price: nonempty.nullable(),
});

const observationBase = z.strictObject({
  diningDate: date,
  observedAt: timestamp,
  evidence: z.array(evidenceSchema).min(1),
});

export const observationSchema = z.discriminatedUnion("status", [
  observationBase.extend({
    status: z.literal("available"),
    slots: z.array(slotSchema).min(1),
  }),
  observationBase.extend({
    status: z.literal("unavailable"),
    // An empty calendar alone cannot establish that released dinner inventory is gone.
    releaseEvidence: evidenceSchema,
    serviceEvidence: evidenceSchema,
  }),
  observationBase.extend({ status: z.literal("non_service") }),
  observationBase.extend({ status: z.literal("unreleased") }),
  observationBase.extend({ status: z.literal("unknown") }),
  observationBase.extend({ status: z.literal("collection_error") }),
]);

export const restaurantCaptureSchema = z
  .strictObject({
    name: nonempty,
    resyUrl,
    address: nonempty.nullable(),
    geography: z.enum(["san_francisco", "outside_san_francisco", "unknown"]),
    eligibility: z.enum(["eligible", "excluded", "unresolved"]),
    reason: nonempty,
    bookingPolicy: nonempty.nullable(),
    evidence: z.array(evidenceSchema).min(1),
    observations: z.array(observationSchema).max(28),
  })
  .superRefine((restaurant, context) => {
    if (restaurant.eligibility === "eligible" && restaurant.geography !== "san_francisco") {
      context.addIssue({
        code: "custom",
        message: "Eligible restaurants must be confirmed within SF",
      });
    }

    const dates = new Set<string>();

    for (const observation of restaurant.observations) {
      if (dates.has(observation.diningDate)) {
        context.addIssue({
          code: "custom",
          message: `Duplicate dining date: ${observation.diningDate}`,
        });
      }

      dates.add(observation.diningDate);
    }
  });

export const collectionSchema = z
  .strictObject({
    schemaVersion: z.literal(1),
    id: nonempty,
    startedAt: timestamp,
    finishedAt: timestamp,
    discoveryUrl: httpUrl,
    discoveryComplete: z.boolean(),
    selection: nonempty,
    collector: nonempty,
    procedure: z.array(nonempty).min(1),
    limitations: z.array(nonempty),
    restaurants: z.array(restaurantCaptureSchema).min(1),
  })
  .superRefine((collection, context) => {
    const anchor = localDate(collection.startedAt);
    const start = Date.parse(collection.startedAt);
    const finish = Date.parse(collection.finishedAt);

    if (finish < start || localDate(collection.finishedAt) !== anchor) {
      context.addIssue({
        code: "custom",
        message: "A collection must finish on its starting SF date",
      });
    }

    const urls = new Set<string>();

    for (const restaurant of collection.restaurants) {
      if (urls.has(restaurant.resyUrl)) {
        context.addIssue({
          code: "custom",
          message: `Duplicate restaurant: ${restaurant.resyUrl}`,
        });
      }

      urls.add(restaurant.resyUrl);
      const sources = [...restaurant.evidence];

      for (const observation of restaurant.observations) {
        sources.push(...observation.evidence);

        if (observation.status === "unavailable") {
          sources.push(observation.releaseEvidence, observation.serviceEvidence);
        }

        const observed = Date.parse(observation.observedAt);

        if (observed < start || observed > finish || localDate(observation.observedAt) !== anchor) {
          context.addIssue({
            code: "custom",
            message: "Observation is outside the collection interval",
          });
        }

        if (observation.diningDate <= anchor || observation.diningDate > addDays(anchor, 28)) {
          context.addIssue({ code: "custom", message: "Dining date is outside days 1–28" });
        }
      }

      if (sources.some((source) => Date.parse(source.observedAt) > finish)) {
        context.addIssue({
          code: "custom",
          message: "Evidence was observed after the collection finished",
        });
      }
    }
  });

export type Collection = z.infer<typeof collectionSchema>;

export type RestaurantCapture = z.infer<typeof restaurantCaptureSchema>;

export type Observation = z.infer<typeof observationSchema>;

export type Evidence = z.infer<typeof evidenceSchema>;

import { addDays } from "./model.ts";
import type { Observation, RestaurantCapture } from "./model.ts";

/** Seating types at the same time are one choice, not evidence of extra capacity. */
export function availableDinnerTimes(observation: Observation): string[] {
  if (observation.status !== "available") return [];

  return [...new Set(observation.slots.map((slot) => slot.time))].toSorted();
}

export function scoreRestaurant(restaurant: RestaurantCapture, anchorDate: string) {
  const observations = new Map(restaurant.observations.map((item) => [item.diningDate, item]));

  return [1, 8, 15, 22].map((startDay) => {
    const counts = {
      available: 0,
      unavailable: 0,
      non_service: 0,
      unreleased: 0,
      unknown: 0,
      collection_error: 0,
      missing: 0,
    };

    let limitedChoice = 0;

    for (let offset = startDay; offset < startDay + 7; offset++) {
      const observation = observations.get(addDays(anchorDate, offset));

      if (observation) {
        counts[observation.status]++;

        if (observation.status === "available" || observation.status === "unavailable") {
          limitedChoice += 1 / (1 + availableDinnerTimes(observation).length);
        }
      } else {
        counts.missing++;
      }
    }

    const assessed = counts.available + counts.unavailable;

    const incomplete =
      counts.unreleased + counts.unknown + counts.collection_error + counts.missing;

    let score: number | null = null;
    let reason: string | null = null;

    if (restaurant.eligibility !== "eligible") {
      reason = restaurant.reason;
    } else if (incomplete > 0) {
      reason =
        "Not every date has a released, assessed dinner service or confirmed non-service status";
    } else if (assessed === 0) {
      reason = "No regular dinner service dates in this band";
    } else {
      // Equal weight for no-opening frequency and limited choice. The reciprocal
      // rewards extra times with diminishing returns, without assuming total capacity.
      score = (50 * (counts.unavailable + limitedChoice)) / assessed;
    }

    return { startDay, endDay: startDay + 6, counts, assessed, score, reason };
  });
}

/* eslint-disable no-await-in-loop -- Rate-limit requests and bound receipt parsing memory; each page determines the next. */
import { randomUUID } from "node:crypto";
import { link, mkdir, readFile, readdir, unlink, writeFile } from "node:fs/promises";
import { join } from "node:path";

import { z } from "zod";

import { addDays, collectionSchema, localDate } from "./model.ts";
import type { Collection, Evidence, Observation, RestaurantCapture } from "./model.ts";
import {
  ResySearch,
  SEARCH_URL,
  searchResponseSchema,
  venueResponseSchema,
  venueUrl,
} from "./resy.ts";
import type { NativeSearchHit, SearchHit, VenueDetails } from "./resy.ts";

const manifestSchema = z.object({
  id: z.string(),
  startedAt: z.iso.datetime(),
  days: z.number().int().min(1).max(28),
  query: z.string(),
});

const searchCaptureSchema = z.object({
  observedAt: z.iso.datetime(),
  day: z.iso.date(),
  page: z.number().int().positive(),
  response: searchResponseSchema,
});

const detailCaptureSchema = z.object({
  observedAt: z.iso.datetime(),
  response: venueResponseSchema,
});

type SearchCapture = z.infer<typeof searchCaptureSchema>;

type DetailCapture = z.infer<typeof detailCaptureSchema>;

const failureSchema = z.object({ observedAt: z.iso.datetime(), message: z.string() });

type Artifact =
  | z.infer<typeof manifestSchema>
  | SearchCapture
  | DetailCapture
  | Collection
  | z.infer<typeof failureSchema>;

type DayCoverage = {
  pages: Set<number>;
  ids: Set<string>;
  rows: number;
  expectedPages: number;
  expectedVenues: number;
  stableTotals: boolean;
};

async function save(path: string, value: Artifact) {
  const partial = `${path}.${randomUUID()}.partial`;
  await writeFile(partial, `${JSON.stringify(value, null, 2)}\n`, { flag: "wx", mode: 0o600 });

  try {
    // Publish a complete file atomically without replacing an existing receipt.
    await link(partial, path);
  } finally {
    await unlink(partial);
  }
}

function source(url: string, observedAt: string, quote: string): Evidence {
  return { url, observedAt, quote };
}

/** Positive evidence suffices for access; absence never automatically means sold out. */
export function observeSearch(hit: SearchHit, day: string, observedAt: string): Observation {
  const base = { diningDate: day, observedAt };

  const evidence = source(
    SEARCH_URL,
    observedAt,
    `All-day search for ${day}, party_size=2; venue ID ${hit.id.resy}, ${hit.name}.`,
  );

  if (hit.is_tock_inventory) {
    return {
      ...base,
      status: "unknown",
      evidence: [
        { ...evidence, quote: `${evidence.quote} Tock inventory, not Resy reservations.` },
      ],
    };
  }

  const availability = hit.availability;
  const slots: Extract<Observation, { status: "available" }>["slots"] = [];

  for (const slot of availability.slots) {
    const date = slot.date.start.slice(0, 10);
    const localTime = slot.date.start.slice(11);
    const time = localTime.slice(0, 5);
    const template = availability.templates[String(slot.template.id)];

    if (date !== day || localTime < "18:00:00" || localTime > "21:00:00") continue;

    if (slot.is_global_dining_access || slot.exclusive.id !== 0 || !slot.exclusive.is_eligible)
      continue;

    if (!template || template.is_event !== 0 || template.is_pickup !== 0) continue;
    slots.push({ time, type: slot.config.type, price: null });
  }

  const times = availability.slots.map((slot) => `${slot.date.start} ${slot.config.type}`);
  evidence.quote += ` Returned ${times.length} slots: ${times.join("; ") || "none"}.`;

  if (availability.status !== null || Object.keys(availability.gating_errors).length > 0) {
    evidence.quote += " Inventory status/gating errors require review.";

    return { ...base, status: "unknown", evidence: [evidence] };
  }

  if (slots.length > 0) return { ...base, status: "available", evidence: [evidence], slots };
  evidence.quote +=
    " No verified qualifying regular dinner slot; release, service and completeness require review.";

  return { ...base, status: "unknown", evidence: [evidence] };
}

function assessRestaurant(
  hit: NativeSearchHit,
  observedAt: string,
  details: DetailCapture | undefined,
): RestaurantCapture {
  const url = venueUrl(hit);

  const evidence = [
    source(
      SEARCH_URL,
      observedAt,
      `Search venue ID ${hit.id.resy}; locality=${hit.locality}; region=${hit.region}; is_tock_inventory=${hit.is_tock_inventory}.`,
    ),
  ];

  const restaurant: RestaurantCapture = {
    name: hit.name,
    resyUrl: url,
    address: null,
    geography: "unknown",
    eligibility: "unresolved",
    reason: "Physical address and regular dinner eligibility require verification.",
    bookingPolicy: null,
    evidence,
    observations: [],
  };

  if (hit.locality && (hit.locality !== "San Francisco" || hit.region !== "CA")) {
    restaurant.geography = "outside_san_francisco";
    restaurant.eligibility = "excluded";
    restaurant.reason = `Search reports ${hit.locality}, ${hit.region}, outside San Francisco.`;

    return restaurant;
  }

  if (!details) return restaurant;

  const { response, observedAt: detailTime } = details;
  const address = response.location;
  restaurant.address = [address.address_1, address.locality, address.region, address.postal_code]
    .filter(Boolean)
    .join(", ");
  evidence.push(
    source(
      url,
      detailTime,
      `Venue ID ${response.id.resy}; address: ${restaurant.address}; country=${address.country_iso3166}; is_active=${response.is_active}.`,
    ),
  );

  if (
    address.address_1 &&
    address.locality.trim().toLowerCase() === "san francisco" &&
    address.region === "CA" &&
    address.country_iso3166 === "US"
  ) {
    restaurant.geography = "san_francisco";
  } else if (address.locality && address.postal_code && !address.postal_code.startsWith("941")) {
    // A 941xx address with a misspelled city stays unresolved, rather than being excluded.
    restaurant.geography = "outside_san_francisco";
    restaurant.eligibility = "excluded";
    restaurant.reason = `Venue details locate this restaurant at ${restaurant.address}, outside San Francisco.`;
  }

  for (const content of response.content) {
    if (content.body && ["need_to_know", "about", "from_the_venue"].includes(content.name)) {
      evidence.push(source(url, detailTime, content.body));
    }
  }

  if (response.is_active !== 1) {
    restaurant.eligibility = "excluded";
    restaurant.reason =
      "Resy marks this listing inactive; not evidence of high reservation demand.";
  }

  return restaurant;
}

/** Rebuild a collection from immutable, sanitized receipts, including an interrupted run. */
export async function assembleSearch(directory: string) {
  const manifest = manifestSchema.parse(
    JSON.parse(await readFile(join(directory, "manifest.json"), "utf8")),
  );

  const files = (await readdir(directory)).filter((name) => name.endsWith(".json"));
  files.sort((a, b) => a.localeCompare(b));
  const details = new Map<number, DetailCapture>();

  for (const file of files.filter((name) => name.startsWith("venue-"))) {
    const detail = detailCaptureSchema.parse(
      JSON.parse(await readFile(join(directory, file), "utf8")),
    );

    details.set(detail.response.id.resy, detail);
  }

  const restaurants = new Map<number, RestaurantCapture>();
  const tockListings = new Map<number, string>();
  const pagesByDay = new Map<string, DayCoverage>();
  let finishedAt = manifest.startedAt;

  for (const file of files.filter((name) => name.startsWith("search-"))) {
    const capture = searchCaptureSchema.parse(
      JSON.parse(await readFile(join(directory, file), "utf8")),
    );

    if (capture.observedAt > finishedAt) finishedAt = capture.observedAt;
    const meta = capture.response.meta;

    const coverage = pagesByDay.get(capture.day) ?? {
      pages: new Set<number>(),
      ids: new Set<string>(),
      rows: 0,
      expectedPages: meta.total_pages,
      expectedVenues: meta.total,
      stableTotals: true,
    };

    coverage.pages.add(capture.page);
    coverage.rows += capture.response.search.hits.length;
    coverage.stableTotals &&=
      meta.total === coverage.expectedVenues && meta.total_pages === coverage.expectedPages;

    for (const hit of capture.response.search.hits) {
      coverage.ids.add(`${hit.is_tock_inventory ? "tock" : "resy"}:${hit.id.resy}`);
    }

    pagesByDay.set(capture.day, coverage);

    for (const hit of capture.response.search.hits) {
      if (hit.is_tock_inventory) {
        tockListings.set(
          hit.id.resy,
          `Excluded external Tock search result: ${hit.name}, ${hit.locality}, ${hit.region}; ID ${hit.id.resy}; https://www.exploretock.com/${hit.url_slug}/. Not a Resy venue page.`,
        );
        continue;
      }

      let restaurant = restaurants.get(hit.id.resy);

      if (!restaurant) {
        restaurant = assessRestaurant(hit, capture.observedAt, details.get(hit.id.resy));
        restaurants.set(hit.id.resy, restaurant);
      }

      if (restaurant.resyUrl !== venueUrl(hit))
        throw new Error(`Conflicting identity for venue ${hit.id.resy}`);

      // Availability-ranked pagination can repeat venues while inventory changes. Keep the first observation.
      if (restaurant.observations.some((observation) => observation.diningDate === capture.day))
        continue;

      if (restaurant.geography === "outside_san_francisco") continue;
      restaurant.observations.push(observeSearch(hit, capture.day, capture.observedAt));
    }
  }

  for (const detail of details.values()) {
    if (detail.observedAt > finishedAt) finishedAt = detail.observedAt;
  }

  for (const restaurant of restaurants.values()) {
    restaurant.observations.sort((a, b) => a.diningDate.localeCompare(b.diningDate));

    if (
      restaurant.eligibility !== "excluded" &&
      restaurant.geography === "san_francisco" &&
      restaurant.observations.some((observation) => observation.status === "available")
    ) {
      restaurant.eligibility = "eligible";
      restaurant.reason =
        "Verified SF street address and public regular dinner inventory in this collection.";
    }
  }

  const coverage = [...pagesByDay].map(([day, result]) => ({
    day,
    pages: result.pages.size,
    expectedPages: result.expectedPages,
    uniqueVenues: result.ids.size,
    expectedVenues: result.expectedVenues,
    duplicateRows: result.rows - result.ids.size,
    reconciled:
      result.stableTotals &&
      result.pages.size === result.expectedPages &&
      result.ids.size === result.expectedVenues &&
      result.rows === result.ids.size &&
      [...result.pages].every((page) => page >= 1 && page <= result.expectedPages),
  }));

  const failures: string[] = [];

  if (files.includes("failure.json")) {
    const failure = failureSchema.parse(
      JSON.parse(await readFile(join(directory, "failure.json"), "utf8")),
    );

    failures.push(`Collection stopped at ${failure.observedAt}: ${failure.message}`);
  }

  const collection = collectionSchema.parse({
    schemaVersion: 1,
    id: manifest.id,
    startedAt: manifest.startedAt,
    finishedAt,
    discoveryUrl: "https://resy.com/cities/san-francisco-ca/search",
    discoveryComplete: false,
    selection: manifest.query
      ? `Search query ${JSON.stringify(manifest.query)}; a convenience pilot, not a citywide ranking.`
      : "All accessible pages of the observed SF search within a 32.2km radius; geographic exclusions retained.",
    collector: "Resy public search API, reconstructed from agent-browser HAR; search-collector-v1",
    procedure: [
      "Replay the browser's public search POST with party_size=2, All Day, page size 20, availability=true (includes zero-slot venues), and Tock inventory included for explicit exclusion.",
      `Observe tomorrow through day ${manifest.days}; collect pages sequentially with one second between requests and no automatic retries.`,
      "Deduplicate venue IDs; verify SF street addresses with GET /3/venue. Retain source text; count only public, non-event, non-pickup slots from 18:00 through 21:00 inclusive.",
      "Keep empty or ambiguous inventory unknown. No automated interpretation of release policies, service calendars, or closures.",
      `Search pagination reconciliation: ${JSON.stringify(coverage)}`,
      "Save allowlisted, Zod-validated responses as immutable receipts. Headers, cookies and reservation tokens are omitted. Assemble receipts without network access; import the resulting collection separately.",
      ...tockListings.values(),
    ],
    limitations: [
      "Search is not an independently verified census of every Resy SF listing, even when returned totals reconcile. Availability-ranked pages can move during collection.",
      "Slot completeness is not guaranteed by an API contract. No-slot dates remain unknown until independently reviewed with release and service evidence.",
      "Official closure, event-only and other-platform policies require human review where inventory does not establish regular dinner access. A positive slot does not prove restaurant popularity.",
      "Prices are not inferred from cancellation fees or template payment flags.",
      ...failures,
      "Uncollected dates and missing venues remain missing, not unavailable. External Tock listings are retained in collection provenance, not assigned invented Resy venue URLs. Nearby-city Resy venues remain excluded restaurant records.",
      ...(coverage.some((day) => !day.reconciled)
        ? ["At least one date's pagination did not reconcile; see per-date coverage."]
        : []),
      ...(coverage.length < manifest.days
        ? [
            "Collection ended before all requested dates were captured; retained receipts are partial.",
          ]
        : []),
    ],
    restaurants: [...restaurants.values()],
  });

  await save(join(directory, "collection.json"), collection);

  return collection;
}

export async function collectSearch(
  directory: string,
  harPath: string,
  days: number,
  query: string,
) {
  const client = await ResySearch.fromHar(harPath);

  const manifest = manifestSchema.parse({
    id: `search-${randomUUID()}`,
    startedAt: new Date().toISOString(),
    days,
    query,
  });

  await mkdir(directory); // Refuse existing directories: a retry is a new immutable snapshot.
  await save(join(directory, "manifest.json"), manifest);
  const anchor = localDate(manifest.startedAt);
  const detailed = new Set<number>();
  const deadline = Date.now() + 60 * 60 * 1000;
  let capturedPages = 0;

  try {
    for (let offset = 1; offset <= days; offset++) {
      const day = addDays(anchor, offset);
      let totalPages = 1;

      for (let page = 1; page <= totalPages; page++) {
        if (Date.now() >= deadline || localDate(new Date().toISOString()) !== anchor) {
          throw new Error("Collection time budget or SF date boundary reached");
        }

        const response = await client.search(day, page, query);

        if (response.meta.page !== page || response.meta.total_pages > 100)
          throw new Error("Unexpected search pagination");
        const observedAt = new Date().toISOString();
        await save(join(directory, `search-${day}-${String(page).padStart(3, "0")}.json`), {
          observedAt,
          day,
          page,
          response,
        });
        capturedPages++;
        totalPages = response.meta.total_pages;
        console.error(
          `${day} page ${page}/${totalPages}: ${response.search.hits.length} listings (${response.meta.total} reported)`,
        );

        for (const hit of response.search.hits) {
          if (
            hit.is_tock_inventory ||
            hit.locality !== "San Francisco" ||
            hit.region !== "CA" ||
            detailed.has(hit.id.resy)
          )
            continue;
          const details: VenueDetails = await client.venue(hit);
          await save(join(directory, `venue-${hit.id.resy}.json`), {
            observedAt: new Date().toISOString(),
            response: details,
          });
          detailed.add(hit.id.resy);
        }
      }
    }
  } catch (error) {
    await save(join(directory, "failure.json"), {
      observedAt: new Date().toISOString(),
      message: error instanceof Error ? error.message : "Collection failed",
    });
    throw error;
  } finally {
    if (capturedPages > 0) {
      const collection = await assembleSearch(directory);
      console.error(
        `Saved ${collection.restaurants.length} restaurant records to ${join(directory, "collection.json")}`,
      );
    }
  }
}

import { readFile } from "node:fs/promises";
import { setTimeout as delay } from "node:timers/promises";

import { z } from "zod";

export const SEARCH_URL = "https://api.resy.com/3/venuesearch/search";

const identity = {
  id: z.object({ resy: z.number().int().positive() }),
  name: z.string().min(1),
  url_slug: z.string().regex(/^[\w-]+$/),
  locality: z.string(),
  region: z.string(),
  location: z.object({ url_slug: z.string().regex(/^[\w-]+$/) }),
};

const slotSchema = z.object({
  date: z.object({
    start: z.string().regex(/^\d{4}-\d{2}-\d{2} (?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d$/),
  }),
  config: z.object({ type: z.string().min(1) }),
  template: z.object({ id: z.number().int() }),
  is_global_dining_access: z.boolean(),
  exclusive: z.object({ id: z.number().int(), is_eligible: z.boolean() }),
});

const nativeHitSchema = z.object({
  ...identity,
  is_tock_inventory: z.literal(false),
  availability: z.object({
    slots: z.array(slotSchema),
    templates: z.record(
      z.string(),
      z.object({
        is_event: z.number().nullable().optional(),
        is_pickup: z.number().nullable().optional(),
      }),
    ),
    // Keep error names, never opaque error payloads or reservation tokens.
    gating_errors: z
      .record(z.string(), z.unknown())
      .transform((errors) => Object.fromEntries(Object.keys(errors).map((name) => [name, true]))),
    status: z.string().nullable(),
  }),
});

export const searchResponseSchema = z.object({
  meta: z.object({
    page: z.number().int().positive(),
    per_page: z.number().int().nonnegative(),
    total: z.number().int().nonnegative(),
    total_pages: z.number().int().nonnegative(),
  }),
  search: z.object({
    hits: z.array(
      z.discriminatedUnion("is_tock_inventory", [
        nativeHitSchema,
        z.object({ ...identity, is_tock_inventory: z.literal(true) }),
      ]),
    ),
  }),
});

export const venueResponseSchema = z.object({
  id: z.object({ resy: z.number().int().positive() }),
  name: z.string(),
  is_active: z.number(),
  location: z.object({
    address_1: z.string().nullable(),
    locality: z.string(),
    region: z.string(),
    postal_code: z.string().nullable(),
    country_iso3166: z.string(),
  }),
  content: z.array(z.object({ name: z.string(), body: z.string().trim().nullable() })),
});

export type SearchHit = z.output<typeof searchResponseSchema>["search"]["hits"][number];

export type NativeSearchHit = Extract<SearchHit, { is_tock_inventory: false }>;

export type VenueDetails = z.output<typeof venueResponseSchema>;

export function venueUrl(hit: NativeSearchHit): string {
  return `https://resy.com/cities/${hit.location.url_slug}/venues/${hit.url_slug}`;
}

export function searchRequest(day: string, page: number, query: string) {
  return {
    availability: true,
    include_tock_inventory: true,
    page,
    per_page: 20,
    slot_filter: { day, party_size: 2 },
    types: ["venue"],
    order_by: "availability",
    geo: { latitude: 37.7577, longitude: -122.4376, radius: 32200 },
    query,
  };
}

const harSchema = z.object({
  log: z.object({
    entries: z.array(
      z.object({
        request: z.object({
          method: z.string(),
          url: z.string(),
          headers: z.array(z.object({ name: z.string(), value: z.string() })),
        }),
        response: z.object({ status: z.number() }),
      }),
    ),
  }),
});

/** Credentials stay in memory. Only public, allowlisted response fields leave this client. */
export class ResySearch {
  private constructor(private readonly headers: Headers) {}

  static async fromHar(path: string): Promise<ResySearch> {
    const har = harSchema.parse(JSON.parse(await readFile(path, "utf8")));

    const entry = har.log.entries.find(
      ({ request, response }) =>
        request.url === SEARCH_URL && request.method === "POST" && response.status === 200,
    );

    if (!entry) throw new Error("HAR must contain a successful Resy search POST");

    const headers = new Headers();

    const allowed = new Set([
      "accept",
      "accept-language",
      "authorization",
      "content-type",
      "referer",
      "user-agent",
      "x-origin",
      "x-session-id",
    ]);

    for (const { name, value } of entry.request.headers) {
      if (allowed.has(name.toLowerCase())) headers.set(name, value);
    }

    if (!headers.has("authorization")) throw new Error("Search HAR has no authorization header");

    return new ResySearch(headers);
  }

  private async request(url: string, body?: ReturnType<typeof searchRequest>): Promise<Response> {
    // Sequential requests, at least one second apart; no automatic retries on blocks or failures.
    await delay(1000);

    const response = await fetch(url, {
      method: body ? "POST" : "GET",
      headers: this.headers,
      body: body ? JSON.stringify(body) : undefined,
      redirect: "error",
      signal: AbortSignal.timeout(20_000),
    });

    if (!response.ok) throw new Error(`Resy returned HTTP ${response.status}`);

    return response;
  }

  async search(day: string, page: number, query: string) {
    const response = await this.request(SEARCH_URL, searchRequest(day, page, query));

    return searchResponseSchema.parse(await response.json());
  }

  async venue(hit: NativeSearchHit): Promise<VenueDetails> {
    const query = new URLSearchParams({
      url_slug: hit.url_slug,
      location: hit.location.url_slug,
    });

    const result = await this.request(`https://api.resy.com/3/venue?${query}`);
    const response = venueResponseSchema.parse(await result.json());

    if (response.id.resy !== hit.id.resy) throw new Error("Venue detail ID does not match search");

    return response;
  }
}

import { createHash } from "node:crypto";

import { and, desc, eq } from "drizzle-orm";
import type { BetterSQLite3Database } from "drizzle-orm/better-sqlite3";

import * as schema from "../db/schema.ts";
import { localDate, SCORE_VERSION } from "./model.ts";
import type { Collection, RestaurantCapture } from "./model.ts";
import { scoreRestaurant } from "./score.ts";

export type ScarcityDatabase = BetterSQLite3Database<typeof schema>;

function storeScores(
  db: ScarcityDatabase,
  collectionId: string,
  restaurant: RestaurantCapture,
  anchorDate: string,
) {
  for (const band of scoreRestaurant(restaurant, anchorDate)) {
    db.insert(schema.scarcityScores)
      .values({
        collectionId,
        resyUrl: restaurant.resyUrl,
        startDay: band.startDay,
        endDay: band.endDay,
        available: band.counts.available,
        unavailable: band.counts.unavailable,
        nonService: band.counts.non_service,
        unreleased: band.counts.unreleased,
        unknown: band.counts.unknown,
        collectionError: band.counts.collection_error,
        missing: band.counts.missing,
        assessed: band.assessed,
        score: band.score,
        reason: band.reason,
      })
      .run();
  }
}

/** Rebuild derived scores atomically; source evidence and import hashes never change. */
export function rescoreCollections(db: ScarcityDatabase) {
  return db.transaction((transaction) => {
    const collections = transaction.select().from(schema.collections).all();

    for (const collection of collections) {
      transaction
        .delete(schema.scarcityScores)
        .where(eq(schema.scarcityScores.collectionId, collection.id))
        .run();

      const snapshots = transaction
        .select()
        .from(schema.restaurantSnapshots)
        .where(eq(schema.restaurantSnapshots.collectionId, collection.id))
        .all();

      for (const snapshot of snapshots) {
        const observations = transaction
          .select({ detail: schema.dinnerObservations.detail })
          .from(schema.dinnerObservations)
          .where(
            and(
              eq(schema.dinnerObservations.collectionId, collection.id),
              eq(schema.dinnerObservations.resyUrl, snapshot.resyUrl),
            ),
          )
          .all()
          .map((row) => row.detail);

        storeScores(
          transaction,
          collection.id,
          { ...snapshot, observations },
          collection.anchorDate,
        );
      }

      transaction
        .update(schema.collections)
        .set({ scoreVersion: SCORE_VERSION })
        .where(eq(schema.collections.id, collection.id))
        .run();
    }

    return { collections: collections.length, scoreVersion: SCORE_VERSION };
  });
}

/** Import one validated, immutable collection atomically. Exact retries are no-ops. */
export function importCollection(db: ScarcityDatabase, collection: Collection) {
  const inputHash = createHash("sha256").update(JSON.stringify(collection)).digest("hex");
  const anchorDate = localDate(collection.startedAt);

  return db.transaction((transaction) => {
    const existing = transaction
      .select()
      .from(schema.collections)
      .where(eq(schema.collections.id, collection.id))
      .get();

    if (existing) {
      if (existing.inputHash !== inputHash) {
        throw new Error(
          `Collection ${collection.id} already exists with different evidence; use a new ID`,
        );
      }

      return { imported: false, restaurants: collection.restaurants.length };
    }

    transaction
      .insert(schema.collections)
      .values({
        id: collection.id,
        inputHash,
        schemaVersion: collection.schemaVersion,
        scoreVersion: SCORE_VERSION,
        startedAt: collection.startedAt,
        finishedAt: collection.finishedAt,
        anchorDate,
        discoveryUrl: collection.discoveryUrl,
        discoveryComplete: collection.discoveryComplete,
        selection: collection.selection,
        collector: collection.collector,
        procedure: collection.procedure,
        limitations: collection.limitations,
      })
      .run();

    for (const restaurant of collection.restaurants) {
      const { observations, ...assessment } = restaurant;
      const identity = { collectionId: collection.id, resyUrl: restaurant.resyUrl };
      transaction
        .insert(schema.restaurantSnapshots)
        .values({
          ...assessment,
          collectionId: collection.id,
        })
        .run();

      for (const observation of observations) {
        transaction
          .insert(schema.dinnerObservations)
          .values({
            ...identity,
            diningDate: observation.diningDate,
            observedAt: observation.observedAt,
            status: observation.status,
            detail: observation,
          })
          .run();
      }

      storeScores(transaction, collection.id, restaurant, anchorDate);
    }

    return { imported: true, restaurants: collection.restaurants.length };
  });
}

export function readRanking(db: ScarcityDatabase) {
  // SQLite sorts NULL last with DESC. Equal scores remain ties, ordered by name for display.
  return db
    .select()
    .from(schema.restaurantRanking)
    .orderBy(desc(schema.restaurantRanking.score), schema.restaurantRanking.name)
    .all();
}

import Database from "better-sqlite3";
import { drizzle } from "drizzle-orm/better-sqlite3";
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import { expect, it, onTestFinished } from "vite-plus/test";

import * as schema from "../db/schema.ts";
import { readRankingPage } from "../ranking/ranking.server.ts";
import { addDays, collectionSchema, localDate, observationSchema, SCORE_VERSION } from "./model.ts";
import type { Observation, RestaurantCapture } from "./model.ts";
import { importCollection, readRanking, rescoreCollections } from "./store.ts";

const evidence = {
  url: "https://resy.com/cities/san-francisco-ca/venues/test-restaurant",
  observedAt: "2026-09-30T22:00:00.000Z",
  quote: "Synthetic test evidence; not a real restaurant observation.",
};

function openTestDatabase() {
  const sqlite = new Database(":memory:");
  onTestFinished(() => {
    sqlite.close();
  });
  sqlite.pragma("foreign_keys = ON");
  const db = drizzle(sqlite, { schema });
  migrate(db, { migrationsFolder: "drizzle" });

  return db;
}

function observation(offset: number, status: Observation["status"] = "available"): Observation {
  const base = {
    diningDate: addDays("2026-09-30", offset),
    observedAt: evidence.observedAt,
    evidence: [evidence],
  };

  if (status === "available") {
    return observationSchema.parse({
      ...base,
      status,
      slots: [{ time: "18:30", type: "Dining room", price: null }],
    });
  }

  if (status === "unavailable") {
    return observationSchema.parse({
      ...base,
      status,
      releaseEvidence: evidence,
      serviceEvidence: evidence,
    });
  }

  return observationSchema.parse({ ...base, status });
}

function restaurant(observations: Observation[]): RestaurantCapture {
  return {
    name: "Synthetic restaurant",
    resyUrl: evidence.url,
    address: "Synthetic SF address",
    geography: "san_francisco",
    eligibility: "eligible",
    reason: "Synthetic regular dinner service",
    bookingPolicy: "Synthetic 28-day release window",
    evidence: [evidence],
    observations,
  };
}

function collection(
  id: string,
  restaurants: RestaurantCapture[],
  startedAt = "2026-09-30T21:00:00Z",
) {
  return collectionSchema.parse({
    schemaVersion: 1,
    id,
    startedAt,
    finishedAt: "2026-09-30T22:10:00Z",
    discoveryUrl: "https://resy.com/cities/san-francisco-ca",
    discoveryComplete: false,
    selection: "Synthetic test fixtures only",
    collector: "test",
    procedure: ["Construct synthetic observations"],
    limitations: ["Not live evidence"],
    restaurants,
  });
}

