                return (
                  <Fragment key={restaurant.resyUrl}>
                    <tr className={cn("hover:bg-background/60 *:px-4.5 *:py-4.25 mobile:*:px-2.25 mobile:*:py-4", expanded && "bg-accent")}>
                      <td>
                        <button
                          className="inline-flex items-center gap-2 text-left leading-[1.4] font-[560] hover:text-link mobile:gap-1.25 mobile:text-xs/[1.4]"
                          type="button"
                          aria-expanded={expanded}
                          onClick={() => onToggle(restaurant.resyUrl)}
                        >
                          <ChevronRight
                            size={15}
                            aria-hidden="true"
                            className={cn("shrink-0 text-muted-foreground mobile:w-3", expanded && "rotate-90")}
                          />
                          <span>{restaurant.name}</span>
                        </button>
                        {group !== "ranked" ? (
                          <p className="mt-1.25 ml-5.75 line-clamp-2 text-[11px] leading-normal text-muted-foreground mobile:ml-4.25 mobile:text-[10px]">
                            {restaurant.eligibility === "eligible"
                              ? restaurant.scoreReason
                              : restaurant.eligibilityReason}
                          </p>
                        ) : null}
                      </td>
                      <td className="w-31 mobile:w-17.5">
                        {restaurant.score === null ? (
                          <span className="text-muted-foreground">
                            <span aria-hidden="true">—</span>
                            <span className="sr-only">Not scored</span>
                          </span>
                        ) : (
                          <>
                            <span className="text-[22px] leading-none font-semibold tracking-[-0.04em] tabular-nums mobile:text-xl/none">{formatScore(restaurant.score)}</span>
                            <div className="mt-2 h-0.75 w-17.5 overflow-hidden rounded-xs bg-border/90 mobile:w-10.5" aria-hidden="true">
                              <span className="block h-full bg-foreground" style={{ width: `${restaurant.score}%` }} />
                            </div>
                          </>
                        )}
                      </td>
                      <td className="tablet:hidden">
                        <div className="grid grid-cols-[repeat(7,14px)] gap-1">
                          {restaurant.week.map((day) => (
                            <DayMark
                              key={day.diningDate}
                              status={day.status}
                              label={`${formatDay(day.diningDate)}: ${statusLabel[day.status]}`}
                            />
                          ))}
                        </div>
                      </td>
                    </tr>
                    {expanded && data.detail?.restaurant.resyUrl === restaurant.resyUrl ? (
                      <tr className="bg-accent">
                        <td colSpan={3} className="px-7 pt-6 pb-7 mobile:px-3 mobile:py-4.5">
                          <RestaurantDetail key={restaurant.resyUrl} detail={data.detail} />
                        </td>
                      </tr>
                    ) : null}
                  </Fragment>
                );
              })}
              {rows.length === 0 ? (
                <tr className="hover:bg-background/60">
                  <td colSpan={3} className="h-32.5 px-4.5 py-4.25 text-center text-muted-foreground mobile:px-2.25 mobile:py-4">
                    {query
                      ? "No matching restaurants in this group. Try another name or status."
                      : "No restaurants in this group yet."}
                  </td>
                </tr>
              ) : null}
            </tbody>
          </table>
        </div>
        <footer className="flex justify-between gap-2.5 py-3.5 text-[11px] text-muted-foreground mobile:flex-col mobile:text-[10px] mobile:leading-[1.7]">
          <span>
            {rows.length} restaurant{rows.length === 1 ? "" : "s"}
            {query ? " matching" : " shown"}
          </span>
        </footer>
      </section>
    </main>
  );
}

import { useState } from "react";
import { ArrowUpRight } from "lucide-react";

import { addDays } from "../scarcity/model.ts";
import { availabilityDayClasses, DayMark } from "./availability-day.tsx";
import { formatDay, formatDinnerTime, formatWeekday, statusLabel } from "./format.ts";
import type { DayStatus } from "./format.ts";
import type { RestaurantDetailData } from "./ranking.functions.ts";

export function RestaurantDetail({ detail }: { detail: RestaurantDetailData }) {
  const { restaurant, observations } = detail;
  const [selectedDate, setSelectedDate] = useState(addDays(restaurant.anchorDate, 1));
  const byDate = new Map(observations.map((observation) => [observation.diningDate, observation]));

  const days = Array.from({ length: 28 }, (_, index) => {
    const diningDate = addDays(restaurant.anchorDate, index + 1);
    const status: DayStatus = byDate.get(diningDate)?.status ?? "missing";

    return { diningDate, status };
  });

  const selected = byDate.get(selectedDate);
  const selectedStatus = selected?.status ?? "missing";
  const showCalendar = restaurant.eligibility !== "excluded" && observations.length > 0;

  return (
    <article aria-label={`${restaurant.name} availability`}>
      <header className="flex flex-wrap items-center justify-between gap-2.5 text-xs/normal text-muted-foreground">
        <p>{restaurant.address ?? "Address not verified"}</p>
        <a className="inline-flex items-center gap-0.75 text-link hover:underline" href={restaurant.resyUrl} target="_blank" rel="noreferrer">
          Open on Resy <ArrowUpRight size={14} aria-hidden="true" />
        </a>
      </header>
      {restaurant.score === null ? (
        <p className="mt-3.5 border-l-2 border-warning-border bg-warning px-3 py-2.5 text-[13px] leading-[1.6] text-warning-emphasis">
          {restaurant.eligibility === "eligible"
            ? restaurant.scoreReason
            : restaurant.eligibilityReason}
        </p>
      ) : null}
      {showCalendar ? (
        <div className="mt-6 grid grid-cols-[minmax(250px,360px)_minmax(0,1fr)] gap-11 tablet:gap-7 mobile:grid-cols-1 mobile:gap-6">
          <section aria-label="Dinner availability by date">
            <h2 className="mb-4 text-[13px] font-[550]">
              {formatDay(days[0].diningDate)} – {formatDay(days[27].diningDate)}
            </h2>
            <div className="grid grid-cols-7 gap-1.5">
              {days.slice(0, 7).map((day) => (
                <span className="pb-0.5 text-center text-[11px] text-muted-foreground" key={day.diningDate}>
                  {formatWeekday(day.diningDate)}
                </span>
              ))}
              {days.map((day) => (
                <button
                  key={day.diningDate}
                  type="button"
                  className={availabilityDayClasses(day.status, "calendar")}
                  data-status={day.status}
                  aria-pressed={day.diningDate === selectedDate}
                  aria-label={`${formatDay(day.diningDate)}: ${statusLabel[day.status]}`}
                  onClick={() => setSelectedDate(day.diningDate)}
                >
                  {Number(day.diningDate.slice(-2))}
                </button>
              ))}
            </div>
            <ul className="mt-3.75 flex list-none flex-wrap gap-x-4 gap-y-2 p-0 text-[11px] text-muted-foreground *:flex *:items-center *:gap-1.25">
              <li>
                <DayMark status="available" />
                Available
              </li>
              <li>
                <DayMark status="unavailable" />
                No opening
              </li>
              <li>
                <DayMark status="non_service" />
                No service
              </li>
              <li>
                <DayMark status="unknown" />
                Unconfirmed
              </li>
            </ul>
          </section>
          <section aria-live="polite">
            <h2 className="text-[15px] font-semibold">{formatDay(selectedDate)}</h2>
            {selected?.status === "available" ? (
              <>
                <p className="mt-1.5 text-[13px] text-muted-foreground">
                  {selected.times.length} dinner time{selected.times.length === 1 ? "" : "s"}{" "}
                  available
                </p>
                <ul className="mt-4 flex list-none flex-wrap gap-2" aria-label="Available dinner times">
                  {selected.times.map((time) => (
                    <li className="rounded-sm border bg-card px-2.5 py-1.5 text-[13px] tabular-nums" key={time}>{formatDinnerTime(time)}</li>
                  ))}
                </ul>
              </>
            ) : (
              <p className="mt-1.5 text-[13px] text-muted-foreground">{statusLabel[selectedStatus]}</p>
            )}
          </section>
        </div>
      ) : null}
    </article>
  );
}

