import { addDays } from "./model.ts";
import type { Observation, RestaurantCapture } from "./model.ts";

/** Seating types at the same time are one choice, not evidence of extra capacity. */
export function availableDinnerTimes(observation: Observation): string[] {
  if (observation.status !== "available") return [];

  return [...new Set(observation.slots.map((slot) => slot.time))].toSorted();
}

export function scoreRestaurant(restaurant: RestaurantCapture, anchorDate: string) {
  const observations = new Map(restaurant.observations.map((item) => [item.diningDate, item]));

  return [1, 8, 15, 22].map((startDay) => {
    const counts = {
      available: 0,
      unavailable: 0,
      non_service: 0,
      unreleased: 0,
      unknown: 0,
      collection_error: 0,
      missing: 0,
    };

    let limitedChoice = 0;

    for (let offset = startDay; offset < startDay + 7; offset++) {
      const observation = observations.get(addDays(anchorDate, offset));

      if (observation) {
        counts[observation.status]++;

        if (observation.status === "available" || observation.status === "unavailable") {
          limitedChoice += 1 / (1 + availableDinnerTimes(observation).length);
        }
      } else {
        counts.missing++;
      }
    }

    const assessed = counts.available + counts.unavailable;

    const incomplete =
      counts.unreleased + counts.unknown + counts.collection_error + counts.missing;

    let score: number | null = null;
    let reason: string | null = null;

    if (restaurant.eligibility !== "eligible") {
      reason = restaurant.reason;
    } else if (incomplete > 0) {
      reason =
        "Not every date has a released, assessed dinner service or confirmed non-service status";
    } else if (assessed === 0) {
      reason = "No regular dinner service dates in this band";
    } else {
      // Equal weight for no-opening frequency and limited choice. The reciprocal
      // rewards extra times with diminishing returns, without assuming total capacity.
      score = (50 * (counts.unavailable + limitedChoice)) / assessed;
    }

    return { startDay, endDay: startDay + 6, counts, assessed, score, reason };
  });
}

  const changed = collection("first", [restaurant([])]);
  expect(() => importCollection(db, changed)).toThrow("different evidence");
  expect(readRanking(db)[0].score).toBe(100);

  const latest = collection("latest", [restaurant([])], "2026-09-30T20:00:00Z");
  latest.finishedAt = "2026-09-30T22:15:00.000Z";
  importCollection(db, collectionSchema.parse(latest));
  importCollection(db, collection("older-imported-last", [full], "2026-09-30T21:30:00Z"));
  expect(readRanking(db)[0]).toMatchObject({ collectionId: "latest", score: null, missing: 7 });
  const page = readRankingPage(db, evidence.url);
  expect(page.restaurants[0].week.map((day) => day.status)).toEqual(Array(7).fill("missing"));
  expect(page.detail).toMatchObject({
    restaurant: { score: null },
    observations: [],
  });
  expect(readRankingPage(db).detail).toBeNull();
  expect(db.select().from(schema.restaurantSnapshots).all()).toHaveLength(3);
});

it("keeps a fixed score as the subset grows and sorts scored restaurants ahead of unresolved ones", () => {
  const db = openTestDatabase();

  const full = restaurant(
    Array.from({ length: 7 }, (_, index) => observation(index + 1, "unavailable")),
  );

  importCollection(db, collection("first", [full]));
  const open = restaurant(Array.from({ length: 7 }, (_, index) => observation(index + 1)));
  open.resyUrl = `${evidence.url}-open`;
  const unresolved = restaurant([]);
  unresolved.resyUrl = `${evidence.url}-unresolved`;
  unresolved.eligibility = "unresolved";
  importCollection(db, collection("expansion", [open, unresolved]));
  expect(readRanking(db).map((row) => row.score)).toEqual([100, 25, null]);
});

it("counts distinct times, averages daily scarcity, and ignores seating-type duplication", () => {
  const db = openTestDatabase();

  const first = observationSchema.parse({
    ...observation(1),
    slots: [
      { time: "18:30", type: "Dining room", price: null },
      { time: "18:30", type: "Counter", price: null },
    ],
  });

  const second = observationSchema.parse({
    ...observation(2),
    slots: [
      { time: "21:00", type: "Dining room", price: null },
      { time: "18:00", type: "Dining room", price: null },
      { time: "19:30", type: "Dining room", price: null },
    ],
  });

  const observations = [
    first,
    second,
    ...Array.from({ length: 5 }, (_, index) => observation(index + 3, "non_service")),
  ];

  importCollection(db, collection("choices", [restaurant(observations)]));

  // One time earns 25 points, three earn 12.5. Average the days, not their counts.
  expect(readRanking(db)[0].score).toBe(18.75);
  const page = readRankingPage(db, evidence.url);
  expect(page.detail?.observations.slice(0, 2)).toEqual([
    { diningDate: "2026-10-01", status: "available", times: ["18:30"] },
    { diningDate: "2026-10-02", status: "available", times: ["18:00", "19:30", "21:00"] },
  ]);
});

it("rescores saved observations without changing evidence or breaking import retries", () => {
  const db = openTestDatabase();

  const input = collection("saved", [
    restaurant(Array.from({ length: 7 }, (_, index) => observation(index + 1))),
  ]);

  importCollection(db, input);
  // Simulate scores persisted by the previous, date-only formula.
  db.update(schema.scarcityScores).set({ score: 0 }).run();
  db.update(schema.collections).set({ scoreVersion: "dinner-date-scarcity-v1" }).run();
  const savedCollection = db.select().from(schema.collections).get();
  const savedObservations = db.select().from(schema.dinnerObservations).all();
  const savedSnapshots = db.select().from(schema.restaurantSnapshots).all();

  expect(rescoreCollections(db)).toEqual({ collections: 1, scoreVersion: SCORE_VERSION });
  expect(readRanking(db)[0].score).toBe(25);
  expect(db.select().from(schema.collections).get()).toEqual({
    ...savedCollection,
    scoreVersion: SCORE_VERSION,
  });

